    let cancelled = false;
    const boot = async () => {
      try {
        const [source, status] = await Promise.all([
          fetch("/portfolio.md").then((response) => response.text()),
          window.LanguageModel?.availability(modelOptions) ??
            Promise.resolve("unavailable" as const),
        ]);
        if (cancelled) return;
        setPortfolio(source);
        setAvailability(status);
        if (status === "available") await createSession(source);
      } catch {
        if (!cancelled) setError("The portfolio source could not be loaded.");
      }
    };
    void boot();
    return () => {
      cancelled = true;
      abortRef.current?.abort();
      sessionRef.current?.destroy();
    };
  }, []);

  const activateModel = () => {
    if (portfolio) {
      setError("");
      setAvailability("downloading");
      void createSession(portfolio);
    }
  };
  const generateCanvas = async (tab: PortfolioTab, requestedQuestion = "") => {
    const session = sessionRef.current;
    if (!session) return;
    abortRef.current?.abort();
    const controller = new AbortController();
    abortRef.current = controller;
    setIsGenerating(true);
    setError("");
    let output = "";
    try {
      const request = requestedQuestion
        ? `Answer the visitor's question directly: “${requestedQuestion}” Start with one concise summary sentence, followed by a brief explanation with only the most relevant supporting details. Use the portfolio source as your only evidence. The selected lens is “${tab.label}”, which may influence emphasis but must not turn the answer into a generic resume. Explain relevant connections, reasoning, or tradeoffs only when the source supports them. Avoid repetition and long lists. Present the answer as a thoughtful, focused portfolio canvas in semantic HTML. Return semantic HTML only.`
        : `Compose the main portfolio canvas for the view “${tab.label}”. ${tab.prompt} Use a clear hierarchy, one unusual but usable layout, and only facts from the source. Return semantic HTML only.`;
      for await (const chunk of session.promptStreaming(request, {
        signal: controller.signal,
      })) {
        output += chunk;
